export default function ProductCard({ product }) {
  return (
    <div className="product-card">
      <img src={product.image} alt="" />

      <h3>{product.title}</h3>
      <p>₹{product.price}</p>
      <p>Size: {product.size}</p>
    </div>
  );
}
